CREATE TABLE "PluginArtifactGeneration" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "pluginId" TEXT NOT NULL, "generation" INTEGER NOT NULL, "version" TEXT NOT NULL, "sha256" TEXT NOT NULL, "installedPath" TEXT NOT NULL, "manifestJson" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'staging', "requiredRolesJson" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "activatedAt" TIMESTAMP(3), CONSTRAINT "PluginArtifactGeneration_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PluginArtifactGeneration_pluginId_generation_key" ON "PluginArtifactGeneration"("pluginId", "generation");
CREATE INDEX "PluginArtifactGeneration_status_createdAt_idx" ON "PluginArtifactGeneration"("status", "createdAt");
CREATE TABLE "PluginArtifactReadiness" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "generationId" UUID NOT NULL, "role" TEXT NOT NULL, "sha256" TEXT NOT NULL, "ready" BOOLEAN NOT NULL, "error" TEXT, "checkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PluginArtifactReadiness_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PluginArtifactReadiness_generationId_role_key" ON "PluginArtifactReadiness"("generationId", "role");
ALTER TABLE "PluginArtifactReadiness" ADD CONSTRAINT "PluginArtifactReadiness_generationId_fkey" FOREIGN KEY ("generationId") REFERENCES "PluginArtifactGeneration"("id") ON DELETE CASCADE ON UPDATE CASCADE;
